    {
      return false;
    }
    if (getNumberOfSeats() <= 0)
    {
      return false;
    }
    Trip currentTrip = getTrip();
    if (currentTrip.getNumberOfSeats() < getNumberOfSeats())
    {
      return false;
    }

    for (Booking booking : getCustomer().getBookings())
    {
      if (booking != this && booking != null && booking.getTrip() != null && booking.overlapsWith(currentTrip))
      {
        return false;
      }
    }

    String bookingTime = getBookingDate().toString();
    String departureTime = currentTrip.getDepartureTime();
    if (bookingTime == null || departureTime == null)
    {
      return false;
    }
    try
    {
      java.text.SimpleDateFormat format = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
      java.util.Date bookingDt = format.parse(bookingTime);
      java.util.Date departureDt = format.parse(departureTime);
      long diffMillis = departureDt.getTime() - bookingDt.getTime();
      long twoHoursMillis = 2L * 60L * 60L * 1000L;
      if (diffMillis <= twoHoursMillis)
      {
        return false;
      }
    }
    catch (java.text.ParseException e)
    {
      return false;
    }

    updateTripSeats();
    return true;
